<script>
import axios from "../../axios_instance";
import { Form } from "vform";
import { VueEditor } from "vue2-editor";
import Datepicker from "vuejs-datepicker";
export default {
  props: {},
  components: {
    VueEditor,
    Datepicker,
    // VueRecaptcha, facebookLogin
  },
  data() {
    return {
      state : { 
                    disabledDates: {
                        to: new Date( new Date().getTime() - 86400000),
                        from: new Date( new Date().getTime() + (86400000 * 2))
                    }
                },
      monthNames: [
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December",
      ],

      base_url: window.base_url,
      api_url: window.api_url,
      DepartmentsItems: [],
      user_data: JSON.parse(this.$localStorage.get("user")),
      token: this.$localStorage.get("d_token"),
      tabs: [],
      report_type: "",
      type_select: 0,
      kraItem: [],
      file_List: [],
      deptSingel: [],
      status: "",
      kpiItem: [],
      mosItem: [],
      deptItems: [],
      monthly_button: false,
      items: [],
      //year: this.$localStorage.get('year') ? this.$localStorage.get('year') : new Date().getFullYear(),
      filterForm: new Form({
        dept_id: "",
        year: this.$localStorage.get("year")
          ? this.$localStorage.get("year")
          : new Date().getFullYear(),
        month: "",
        user_id: "",
      }),
      mail_comment: [],
      daliy_mailForm: new Form({
        toDate: new Date().toISOString().slice(0,10) ,
        fromDate:   new Date(new Date( new Date().getTime() + (86400000 * 2))).toISOString().slice(0,10)  ,
        mailcc1: "",
        mailcc2: "",
        mailcc3: "",
        dept_id: "",
        report_id: "",
        comment: "",
        item: [],
      }),
    };
  },
  created() {
    const d = new Date();
    this.current_month = d.getMonth();
    this.role_id = this.user_data.role_id;
    if(this.role_id == 5 ){
        this.daliy_mailForm.dept_id = this.user_data.dept_id;
    }
    if (
      this.role_id == 5 ||
      this.user_data.dept_id != "" ||
      this.user_data.dept_id
    ) {
      this.getDepartment().then(({ data }) => {
        if (data.success) {
          this.deptSingel = data.data;
          this.monthly_button = this.deptSingel.monthly_date_range.status;
          console.log(this.deptSingel.monthly_date_range.status);
        }
      });
    }
    this.getDept();
    this.tabs = [
      { id: "work_with_plan", name: " Work with plan" },
      { id: "without_plan", name: "Without plan" },
      { id: "undone", name: "Undone" },
      { id: "others", name: "Others" },
      //{'id' : 'single_page' , 'name' : 'Single Page' },
      //{'id' : 'wing_report' , 'name' : 'Wing Report' }
    ];
    this.getDepartment();
  },
  methods: {
    hide_pop_permission() {
      this.$modal.hide("popup-permission");
    },
    show_pop_permission(item) {
      this.mail_comment = item;
      console.log(this.mail_comment);
      this.$modal.show("popup-permission");
    },
    hide_pop() {
      this.$modal.hide("popup-singel");
    },
    show_pop(item) {
      this.mail_comment = item;
      console.log(this.mail_comment);
      this.$modal.show("popup-singel");
    },
    hide_pop_singel() {
      this.$modal.hide("singel");
    },
    singenPage() {
      this.$modal.show("singel");
    },
    hide_pop_singel2() {
      this.$modal.hide("singel2");
    },
    singenPage2() {
      this.$modal.show("singel2");
    },
    tabsSet(id, index) {
      this.report_type = id;
      this.type_select = index;
    },
    fileDownload(id) {
      window.open(this.api_url + "monthly_report_download/" + id, "_blank");
    },
    open_file(id) {
      console.log(id);
    },
    async row_delete(id) {
      await axios
        .delete(this.api_url + "monthly_reports/" + id, {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.token ? `Bearer ${this.token}` : "",
          },
        })
        .then((res) => {
          console.log(res);

          if (res.data.success) {
            this.$toasted.show(res.data.message, {
              theme: "bubble",
              duration: 5000,
              position: "bottom-right",
            });
          }
          this.getItems();
          //loader.hide();
        });
    },
    async delete_row(id) {
      this.$swal({
        title: "Are you sure?",
        text: "Are you sure you want to delete?",
        icon: "warning",
        buttons: true,
        dangerMode: true,
      }).then((data) => {
        if (data) {
          this.row_delete(id);
        } else {
          // loader.hide();
          this.$swal("Your task status is not change!");
        }
      });

      console.log(id);
      let loader = this.$loading.show();
      try {
        await axios
          .delete(this.api_url + "daily_schedules/" + id, {
            headers: {
              "Content-Type": "application/json",
              Authorization: this.token ? `Bearer ${this.token}` : "",
            },
          })
          .then(({ res }) => {
            if (res.data.success) {
              this.$toasted.show(res.data.message, {
                theme: "bubble",
                duration: 5000,
                position: "bottom-right",
              });
            }
            loader.hide();
          });
      } catch (error) {
        loader.hide();
      }
    },
